// tools/test/test-app-cloner-generated-literals.cjs

/**
 * ============================================================================
 * MODULE: App Cloner Generated Literals - Behavioral Guard
 * DESCRIPTION:
 * Compiles and round-trips hostile values through the real launcher-literal
 * emitter, then executes a shortcut generated by the production shell script.
 * ============================================================================
 */

'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');
const { bashExecutable } = require('../lib/git-bash.cjs');

const ROOT = path.resolve(__dirname, '..', '..');
const RESOURCES = path.join(
	ROOT,
	'static',
	'ergopti_plus',
	'macos',
	'apps',
	'App Cloner.app',
	'Contents',
	'Resources'
);
const EMITTER = path.join(RESOURCES, 'quote_launcher_values.py');
const CLONE_SCRIPT = path.join(RESOURCES, 'clone_app.sh');
const SHORTCUT_SCRIPT = path.join(RESOURCES, 'make_shortcut.sh');
const PY_CANDIDATES = ['python3', 'python'];
const results = [];

function test(name, ok, detail = '') {
	results.push({ name, ok, detail });
}

function resolveProgram(candidates) {
	for (const candidate of candidates) {
		const probe = spawnSync(candidate, ['--version'], { encoding: 'utf8' });
		if (!probe.error && probe.status === 0) return candidate;
	}
	return null;
}

function toBashPath(filePath) {
	const normalized = path.resolve(filePath).replace(/\\/g, '/');
	if (process.platform !== 'win32') return normalized;
	const match = normalized.match(/^([A-Za-z]):(\/.*)$/);
	if (!match) throw new Error(`cannot convert path for Bash: ${filePath}`);
	return `/${match[1].toLowerCase()}${match[2]}`;
}

function writeExecutable(filePath, source) {
	fs.writeFileSync(filePath, source, { encoding: 'utf8', mode: 0o755 });
	fs.chmodSync(filePath, 0o755);
}

function decodeNulFields(buffer) {
	const fields = buffer.toString('utf8').split('\0');
	if (fields[fields.length - 1] === '') fields.pop();
	return fields;
}

const python = resolveProgram(PY_CANDIDATES);
const bash = bashExecutable();
if (!python) {
	console.error(`Required interpreter unavailable: python=${python}`);
	process.exit(1);
}

const realPython = spawnSync(bash, ['-c', 'command -v "$1"', 'python-runtime', python], {
	encoding: 'utf8'
});
if (realPython.status !== 0 || !realPython.stdout.trim()) {
	throw new Error(`Required Python unavailable in Bash: ${realPython.stderr}`);
}

const hostile = [
	'He said "hi" and $(touch should-not-run)',
	"apostrophe ' plus backslash \\\ and $HOME `uname`",
	'first line\nsecond line\\'
];
const fixtureRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'ergopti-launcher-literals-'));

try {
	const shellEmission = spawnSync(
		python,
		[EMITTER, 'shell', 'VALUE_ONE', hostile[0], 'VALUE_TWO', hostile[1], 'VALUE_THREE', hostile[2]],
		{ encoding: 'utf8' }
	);
	const shellFile = path.join(fixtureRoot, 'roundtrip.sh');
	fs.writeFileSync(
		shellFile,
		`#!/usr/bin/env bash\n${shellEmission.stdout || ''}` +
			'printf \'%s\\0\' "$VALUE_ONE" "$VALUE_TWO" "$VALUE_THREE"\n',
		'utf8'
	);
	const shellSyntax = spawnSync(bash, ['-n', toBashPath(shellFile)], { encoding: 'utf8' });
	const shellRoundtrip = spawnSync(bash, [toBashPath(shellFile)], { encoding: null });
	test(
		'shell literals compile after quotes, substitutions, backslashes, and newlines',
		shellEmission.status === 0 && shellSyntax.status === 0,
		JSON.stringify({ emission: shellEmission.stderr, syntax: shellSyntax.stderr })
	);
	test(
		'shell literals round-trip byte-exact without executing their contents',
		shellRoundtrip.status === 0 &&
			JSON.stringify(decodeNulFields(shellRoundtrip.stdout)) === JSON.stringify(hostile),
		(shellRoundtrip.stderr || Buffer.alloc(0)).toString('utf8')
	);

	const pythonEmission = spawnSync(
		python,
		[
			EMITTER,
			'python',
			'VALUE_ONE',
			hostile[0],
			'VALUE_TWO',
			hostile[1],
			'VALUE_THREE',
			hostile[2]
		],
		{ encoding: 'utf8' }
	);
	const pythonFile = path.join(fixtureRoot, 'roundtrip.py');
	fs.writeFileSync(
		pythonFile,
		`${pythonEmission.stdout || ''}\nimport json\n` +
			'print(json.dumps([VALUE_ONE, VALUE_TWO, VALUE_THREE], ensure_ascii=False))\n',
		'utf8'
	);
	const pythonCompile = spawnSync(python, ['-m', 'py_compile', pythonFile], { encoding: 'utf8' });
	const pythonRoundtrip = spawnSync(python, [pythonFile], { encoding: 'utf8' });
	let pythonValues = [];
	try {
		pythonValues = JSON.parse((pythonRoundtrip.stdout || '').trim());
	} catch {
		/* reported below */
	}
	test(
		'Python literals compile after quotes, substitutions, backslashes, and newlines',
		pythonEmission.status === 0 && pythonCompile.status === 0,
		JSON.stringify({ emission: pythonEmission.stderr, compile: pythonCompile.stderr })
	);
	test(
		'Python literals round-trip byte-exact',
		pythonRoundtrip.status === 0 && JSON.stringify(pythonValues) === JSON.stringify(hostile),
		pythonRoundtrip.stderr || pythonRoundtrip.stdout
	);

	const cloneSource = fs.readFileSync(CLONE_SCRIPT, 'utf8');
	test(
		'clone_app routes both generated languages through the literal emitter',
		cloneSource.includes('"$QUOTE_HELPER" shell') &&
			cloneSource.includes('"$QUOTE_HELPER" python') &&
			!cloneSource.includes('LAUNCHER_ARGS_LITERAL') &&
			!cloneSource.includes('OPEN_ARG="${OPEN_ARG}"') &&
			!cloneSource.includes('OPEN_ARG   = "${OPEN_ARG}"')
	);

	const plistName = 'A&B <Clone> "quoted" \'single\'';
	const xmlEmission = spawnSync(python, [EMITTER, 'xml', plistName], { encoding: 'utf8' });
	test(
		'XML literals escape every plist metacharacter through the production emitter',
		xmlEmission.status === 0 &&
			xmlEmission.stdout === 'A&amp;B &lt;Clone&gt; &quot;quoted&quot; &apos;single&apos;',
		xmlEmission.stderr || xmlEmission.stdout
	);

	const plistBody = cloneSource.match(/cat > "\$CONTENTS\/Info\.plist" <<PLIST\n([\s\S]*?)\nPLIST/);
	const plistFile = path.join(fixtureRoot, 'Info.plist');
	const renderedPlist = plistBody
		? plistBody[1]
				.replaceAll('${UNIQUE_ID}', 'fr.example.clone')
				.replaceAll('${safe_name_xml}', xmlEmission.stdout || '')
		: '';
	fs.writeFileSync(plistFile, `${renderedPlist}\n`, 'utf8');
	const plistRoundtrip = spawnSync(
		python,
		[
			'-c',
			'import plistlib,sys; data=plistlib.load(open(sys.argv[1], "rb")); ' +
				'assert data["CFBundleName"] == sys.argv[2]; ' +
				'assert data["CFBundleDisplayName"] == sys.argv[2]',
			plistFile,
			plistName
		],
		{ encoding: 'utf8' }
	);
	test(
		'the actual generated Info.plist round-trips a hostile clone name',
		xmlEmission.status === 0 &&
			plistBody !== null &&
			!renderedPlist.includes('${safe_name}') &&
			plistRoundtrip.status === 0,
		plistRoundtrip.stderr || renderedPlist
	);
	test(
		'clone_app validates the generated plist before reporting the destination',
		cloneSource.includes('/usr/bin/plutil -lint "$CONTENTS/Info.plist"')
	);

	const shellBody = cloneSource.match(
		/cat >> "\$LAUNCHER" <<'LAUNCHER_BODY'\n([\s\S]*?)\nLAUNCHER_BODY/
	);
	const actualShellEmission = spawnSync(
		python,
		[
			EMITTER,
			'shell',
			'UNIQUE_ID',
			'fr.example.hostile',
			'APP_FAMILY',
			'vscode',
			'USER_DATA_DIR',
			hostile[0],
			'SHARED_EXT_DIR',
			hostile[1],
			'OPEN_ARG',
			hostile[2],
			'SRC_EXE',
			hostile[0],
			'SOURCE_APP',
			hostile[1]
		],
		{ encoding: 'utf8' }
	);
	const cloneLauncher = path.join(fixtureRoot, 'clone-launcher.zsh');
	fs.writeFileSync(
		cloneLauncher,
		`#!/usr/bin/env zsh\n${actualShellEmission.stdout || ''}` +
			(shellBody ? `${shellBody[1]}\n` : ''),
		'utf8'
	);
	const cloneSyntax = spawnSync(bash, ['-n', toBashPath(cloneLauncher)], { encoding: 'utf8' });
	test(
		'the actual generated clone launcher body compiles with hostile assignments',
		actualShellEmission.status === 0 && shellBody !== null && cloneSyntax.status === 0,
		cloneSyntax.stderr || actualShellEmission.stderr
	);

	const pythonBody = cloneSource.match(
		/cat >> "\$RES\/pwa_launcher\.py" << 'PYEOF'\n([\s\S]*?)\nPYEOF/
	);
	const actualPythonEmission = spawnSync(
		python,
		[EMITTER, 'python', 'OPEN_ARG', hostile[0], 'CLONE_NAME', hostile[1], 'SOURCE_APP', hostile[2]],
		{ encoding: 'utf8' }
	);
	const pwaLauncher = path.join(fixtureRoot, 'pwa_launcher.py');
	fs.writeFileSync(
		pwaLauncher,
		`${actualPythonEmission.stdout || ''}` + (pythonBody ? `${pythonBody[1]}\n` : ''),
		'utf8'
	);
	const pwaCompile = spawnSync(python, ['-m', 'py_compile', pwaLauncher], { encoding: 'utf8' });
	test(
		'the actual generated PWA launcher body compiles with hostile assignments',
		actualPythonEmission.status === 0 && pythonBody !== null && pwaCompile.status === 0,
		pwaCompile.stderr || actualPythonEmission.stderr
	);

	const fakeBin = path.join(fixtureRoot, 'bin');
	const home = path.join(fixtureRoot, 'home');
	const capture = path.join(fixtureRoot, 'shortcut-args.bin');
	const marker = path.join(fixtureRoot, 'command-substitution-ran');
	fs.mkdirSync(fakeBin, { recursive: true });
	fs.mkdirSync(home, { recursive: true });
	writeExecutable(path.join(fakeBin, 'python3'), '#!/usr/bin/env bash\nexec "$REAL_PYTHON" "$@"\n');
	writeExecutable(
		path.join(fakeBin, 'qlmanage'),
		`#!/usr/bin/env bash
set -eu
out=''
while [ "$#" -gt 0 ]; do if [ "$1" = '-o' ]; then shift; out="$1"; fi; shift; done
mkdir -p "$out"; printf png > "$out/preview.png"
`
	);
	writeExecutable(
		path.join(fakeBin, 'sips'),
		`#!/usr/bin/env bash
set -eu
out=''
while [ "$#" -gt 0 ]; do if [ "$1" = '--out' ]; then shift; out="$1"; fi; shift; done
mkdir -p "$(dirname "$out")"; printf png > "$out"
`
	);
	writeExecutable(
		path.join(fakeBin, 'iconutil'),
		`#!/usr/bin/env bash
set -eu
out=''
while [ "$#" -gt 0 ]; do if [ "$1" = '-o' ]; then shift; out="$1"; fi; shift; done
printf icns > "$out"
`
	);
	writeExecutable(
		path.join(fakeBin, 'code'),
		'#!/usr/bin/env bash\nprintf \'%s\\0\' "$@" > "$CAPTURE_PATH"\n'
	);
	writeExecutable(path.join(fakeBin, 'osascript'), '#!/usr/bin/env bash\nexit 0\n');
	writeExecutable(path.join(fakeBin, 'sleep'), '#!/usr/bin/env bash\nexit 0\n');

	const markerBash = toBashPath(marker);
	const maliciousApp = `/Applications/A$(touch '${markerBash}')B"\\Name.app`;
	const maliciousTarget = `target "$(touch '${markerBash}')"\\\nnext`;
	const generator = spawnSync(
		bash,
		[toBashPath(SHORTCUT_SCRIPT), 'Shortcut', maliciousTarget, maliciousApp, '#123456', 'S'],
		{
			cwd: fixtureRoot,
			encoding: 'utf8',
			env: {
				...process.env,
				HOME: toBashPath(home),
				REAL_PYTHON: realPython.stdout.trim(),
				PATH: `${toBashPath(fakeBin)}:${process.env.PATH || ''}`
			}
		}
	);
	const generated = path.join(home, 'Desktop', 'Shortcut.app', 'Contents', 'MacOS', 'open_target');
	const generatedSyntax = fs.existsSync(generated)
		? spawnSync(bash, ['-n', toBashPath(generated)], { encoding: 'utf8' })
		: { status: null };
	const generatedRun = fs.existsSync(generated)
		? spawnSync(bash, [toBashPath(generated)], {
				encoding: 'utf8',
				env: {
					...process.env,
					CAPTURE_PATH: toBashPath(capture),
					PATH: `${toBashPath(fakeBin)}:${process.env.PATH || ''}`
				}
			})
		: { status: null };
	const captured = fs.existsSync(capture) ? decodeNulFields(fs.readFileSync(capture)) : [];
	test(
		'the production shortcut generator emits a syntactically valid hostile launcher',
		generator.status === 0 && generatedSyntax.status === 0,
		JSON.stringify({ generator: generator.stderr, syntax: generatedSyntax.stderr })
	);
	test(
		'the generated shortcut preserves arguments without command substitution',
		generatedRun.status === 0 &&
			!fs.existsSync(marker) &&
			JSON.stringify(captured) === JSON.stringify(['-n', maliciousTarget]),
		JSON.stringify({ status: generatedRun.status, captured, stderr: generatedRun.stderr })
	);
	writeExecutable(path.join(fakeBin, 'date'), "#!/usr/bin/env bash\nprintf '%s\\n' 1700000000\n");
	const setupEnd = cloneSource.indexOf('# Resolve source app');
	if (setupEnd < 0) throw new Error('clone setup boundary is missing');
	const cloneSetup = cloneSource.slice(0, setupEnd);
	const profileStart = cloneSource.indexOf('# Per-clone user-data-dir');
	const profileEnd = cloneSource.indexOf('# VSCode-specific extras:', profileStart);
	if (profileStart < 0 || profileEnd <= profileStart) {
		throw new Error('clone profile initialization boundary is missing');
	}
	// Native source-app inspection between these blocks does not allocate the
	// profile. Execute both actual owners while leaving that OS boundary out.
	const profileSetup = cloneSource.slice(profileStart, profileEnd);
	const nativeFixturePath = (value) =>
		path.join(fixtureRoot, path.posix.relative(toBashPath(fixtureRoot), value));
	const cloneDestinations = [];
	const cloneProfiles = [];
	for (let index = 0; index < 3; index += 1) {
		const run = spawnSync(
			bash,
			[
				'-c',
				`${cloneSetup}\n${profileSetup}\nCLONE_COMPLETE=1\nprintf '%s\\0' "$DEST" "$USER_DATA_DIR"\n`,
				toBashPath(CLONE_SCRIPT),
				toBashPath(fixtureRoot),
				'Clone collision'
			],
			{
				encoding: null,
				env: {
					...process.env,
					HOME: toBashPath(home),
					REAL_PYTHON: realPython.stdout.trim(),
					PATH: `${toBashPath(fakeBin)}:${process.env.PATH || ''}`
				}
			}
		);
		if (run.status !== 0) throw new Error(`clone setup failed: ${run.stderr}`);
		const [reported, profile] = decodeNulFields(run.stdout);
		const destination = nativeFixturePath(reported);
		cloneDestinations.push(destination);
		cloneProfiles.push(nativeFixturePath(profile));
		fs.writeFileSync(path.join(destination, 'owned-marker'), String(index));
		fs.writeFileSync(path.join(nativeFixturePath(profile), 'profile-marker'), String(index));
	}
	test(
		'the actual clone setup reserves distinct bundles and preserves previous contents',
		new Set(cloneDestinations).size === 3 &&
			cloneDestinations.every(
				(destination, index) =>
					fs.readFileSync(path.join(destination, 'owned-marker'), 'utf8') === String(index)
			),
		JSON.stringify(cloneDestinations)
	);
	test(
		'repeated clone names keep distinct data profiles and preserve existing profile contents',
		new Set(cloneProfiles).size === 3 &&
			cloneProfiles.every(
				(profile, index) =>
					path.basename(profile) === path.basename(cloneDestinations[index], '.app') &&
					fs.readFileSync(path.join(profile, 'profile-marker'), 'utf8') === String(index)
			),
		JSON.stringify({ destinations: cloneDestinations, profiles: cloneProfiles })
	);
	test(
		'the first clone keeps its original unsuffixed data profile',
		cloneProfiles[0] ===
			path.join(home, 'Library', 'Application Support', 'AppCloner', 'Clone collision'),
		JSON.stringify(cloneProfiles)
	);

	const rollbackHome = path.join(fixtureRoot, 'rollback-home');
	fs.mkdirSync(path.join(rollbackHome, 'Applications'), { recursive: true });
	const preserved = path.join(rollbackHome, 'Applications', 'Rollback.app');
	fs.mkdirSync(preserved);
	fs.writeFileSync(path.join(preserved, 'owned-marker'), 'pre-existing bundle');
	const preservedLink = path.join(rollbackHome, 'Applications', 'Rollback_1.app');
	fs.symlinkSync(preserved, preservedLink, 'junction');
	const rollbackBin = path.join(fixtureRoot, 'rollback-bin');
	fs.mkdirSync(rollbackBin);
	const realMktemp = spawnSync(bash, ['-c', 'command -v mktemp'], { encoding: 'utf8' });

	writeExecutable(
		path.join(rollbackBin, 'python3'),
		'#!/usr/bin/env bash\nexec "$REAL_PYTHON" "$@"\n'
	);
	if (realMktemp.status !== 0 || !realMktemp.stdout.trim()) {
		throw new Error(`Required mktemp unavailable: ${realMktemp.stderr}`);
	}
	// Keep native temporary paths inside the owned fixture, including Git Bash's
	// distinct /tmp mount on Windows. The real allocator still creates them.
	writeExecutable(
		path.join(rollbackBin, 'mktemp'),
		'#!/usr/bin/env bash\nset -eu\nexec "$REAL_MKTEMP" -d "$OWNED_TMP_TEMPLATE"\n'
	);
	const runCloneSetup = (tail, prefixBin = rollbackBin) =>
		spawnSync(
			bash,
			[
				'-c',
				`${cloneSetup}\n${tail}`,
				toBashPath(CLONE_SCRIPT),
				toBashPath(fixtureRoot),
				'Rollback'
			],
			{
				encoding: 'utf8',
				timeout: 10000,
				env: {
					...process.env,
					HOME: toBashPath(rollbackHome),
					REAL_MKTEMP: realMktemp.stdout.trim(),
					REAL_PYTHON: realPython.stdout.trim(),
					OWNED_TMP_TEMPLATE: `${toBashPath(fixtureRoot)}/rollback-work.XXXXXX`,
					PATH: `${toBashPath(prefixBin)}:${process.env.PATH || ''}`
				}
			}
		);
	const failureBin = path.join(fixtureRoot, 'allocation-failure-bin');
	fs.mkdirSync(failureBin);
	writeExecutable(
		path.join(failureBin, 'mktemp'),
		'#!/usr/bin/env bash\necho owned-allocation-failure >&2\nexit 73\n'
	);
	writeExecutable(
		path.join(failureBin, 'python3'),
		'#!/usr/bin/env bash\nexec "$REAL_PYTHON" "$@"\n'
	);
	const unavailablePythonBin = path.join(fixtureRoot, 'unavailable-python-bin');
	fs.mkdirSync(unavailablePythonBin);
	writeExecutable(
		path.join(unavailablePythonBin, 'python3'),
		'#!/usr/bin/env bash\necho required-python-unavailable >&2\nexit 127\n'
	);
	const unavailablePython = runCloneSetup('printf unexpected-success', unavailablePythonBin);
	test(
		'cleanup runtime absence fails before reserving any clone destination',
		unavailablePython.status === 127 &&
			unavailablePython.stdout.includes('required-python-unavailable') &&
			fs.readdirSync(path.dirname(preserved)).length === 2,
		JSON.stringify({
			status: unavailablePython.status,
			stdout: unavailablePython.stdout,
			stderr: unavailablePython.stderr
		})
	);

	const allocationFailure = runCloneSetup('printf unexpected-success', failureBin);
	test(
		'failed temporary-directory allocation removes only its reserved clone bundle',
		allocationFailure.status === 73 &&
			allocationFailure.stdout.includes('owned-allocation-failure') &&
			!fs.existsSync(path.join(rollbackHome, 'Applications', 'Rollback_2.app')),
		JSON.stringify({
			status: allocationFailure.status,
			stdout: allocationFailure.stdout,
			stderr: allocationFailure.stderr
		})
	);
	const lateFailure = runCloneSetup('printf "%s\\0%s\\0" "$DEST" "$TMPDIR_WORK"; exit 74');
	const [failedDestination, failedTemporary] = decodeNulFields(Buffer.from(lateFailure.stdout));
	test(
		'a later failure removes its reserved bundle and temporary workspace without swallowing the error',
		lateFailure.status === 74 &&
			failedDestination &&
			failedTemporary &&
			!fs.existsSync(nativeFixturePath(failedDestination)) &&
			!fs.existsSync(nativeFixturePath(failedTemporary)),
		JSON.stringify({
			status: lateFailure.status,
			stdout: lateFailure.stdout,
			stderr: lateFailure.stderr
		})
	);
	const interrupted = runCloneSetup(
		'printf "%s\\0%s\\0" "$DEST" "$TMPDIR_WORK"; kill -TERM $$; printf unexpected-success'
	);
	const [interruptedDestination, interruptedTemporary] = decodeNulFields(
		Buffer.from(interrupted.stdout)
	);
	test(
		'cancelling a clone transaction removes its owned bundle and temporary workspace',
		interrupted.status === 143 &&
			interruptedDestination &&
			interruptedTemporary &&
			!fs.existsSync(nativeFixturePath(interruptedDestination)) &&
			!fs.existsSync(nativeFixturePath(interruptedTemporary)) &&
			!interrupted.stdout.includes('unexpected-success'),
		JSON.stringify({
			status: interrupted.status,
			signal: interrupted.signal,
			stdout: interrupted.stdout,
			stderr: interrupted.stderr
		})
	);
	const replaced = runCloneSetup(
		'mv "$DEST" "$DEST.held"; mkdir "$DEST"; printf foreign > "$DEST/foreign-marker"; printf "%s\\0%s\\0" "$DEST" "$TMPDIR_WORK"; exit 75'
	);
	const [replacedDestination, replacedTemporary] = decodeNulFields(Buffer.from(replaced.stdout));
	test(
		'rollback refuses a replacement directory and still retires its temporary workspace',
		replaced.status === 75 &&
			replacedDestination &&
			replacedTemporary &&
			replaced.stdout.includes('reserved bundle ownership changed; refusing cleanup') &&
			fs.readFileSync(
				path.join(nativeFixturePath(replacedDestination), 'foreign-marker'),
				'utf8'
			) === 'foreign' &&
			fs.statSync(`${nativeFixturePath(replacedDestination)}.held`).isDirectory() &&
			!fs.existsSync(nativeFixturePath(replacedTemporary)),
		JSON.stringify({ status: replaced.status, stdout: replaced.stdout, stderr: replaced.stderr })
	);
	const symlinkReplacement = runCloneSetup(
		'mv "$DEST" "$DEST.held"; ln -s "$DEST.held" "$DEST"; printf "%s\\0%s\\0" "$DEST" "$TMPDIR_WORK"; exit 76'
	);
	const [symlinkDestination, symlinkTemporary] = decodeNulFields(
		Buffer.from(symlinkReplacement.stdout)
	);
	test(
		'rollback refuses a replacement symbolic link without following or deleting it',
		symlinkReplacement.status === 76 &&
			symlinkDestination &&
			symlinkTemporary &&
			symlinkReplacement.stdout.includes('reserved bundle ownership changed; refusing cleanup') &&
			fs.lstatSync(nativeFixturePath(symlinkDestination)).isSymbolicLink() &&
			fs.statSync(`${nativeFixturePath(symlinkDestination)}.held`).isDirectory() &&
			!fs.existsSync(nativeFixturePath(symlinkTemporary)),
		JSON.stringify({
			status: symlinkReplacement.status,
			stdout: symlinkReplacement.stdout,
			stderr: symlinkReplacement.stderr
		})
	);

	const cleanupFailureBin = path.join(fixtureRoot, 'cleanup-failure-bin');
	fs.mkdirSync(cleanupFailureBin);
	writeExecutable(
		path.join(cleanupFailureBin, 'mktemp'),
		'#!/usr/bin/env bash\nexec "$REAL_MKTEMP" -d "$OWNED_TMP_TEMPLATE"\n'
	);
	writeExecutable(
		path.join(cleanupFailureBin, 'python3'),
		'#!/usr/bin/env bash\nif [[ "$#" == 3 ]]; then echo owned-bundle-cleanup-failure >&2; exit 77; fi\nexec "$REAL_PYTHON" "$@"\n'
	);
	const cleanupFailure = runCloneSetup(
		'printf "%s\\0%s\\0" "$DEST" "$TMPDIR_WORK"; exit 74',
		cleanupFailureBin
	);
	const [uncleanedDestination, cleanedTemporary] = decodeNulFields(
		Buffer.from(cleanupFailure.stdout)
	);
	test(
		'a bundle cleanup failure preserves the primary error and still retires temporary files',
		cleanupFailure.status === 74 &&
			uncleanedDestination &&
			cleanedTemporary &&
			cleanupFailure.stdout.includes('owned-bundle-cleanup-failure') &&
			fs.statSync(nativeFixturePath(uncleanedDestination)).isDirectory() &&
			!fs.existsSync(nativeFixturePath(cleanedTemporary)),
		JSON.stringify({
			status: cleanupFailure.status,
			stdout: cleanupFailure.stdout,
			stderr: cleanupFailure.stderr
		})
	);
	const identityFailureBin = path.join(fixtureRoot, 'identity-failure-bin');
	fs.mkdirSync(identityFailureBin);
	writeExecutable(
		path.join(identityFailureBin, 'python3'),
		'#!/usr/bin/env bash\nif [[ "$1" == "-" && "$#" == 2 ]]; then echo owned-identity-capture-failure >&2; exit 78; fi\nexec "$REAL_PYTHON" "$@"\n'
	);
	const beforeIdentityFailure = fs.readdirSync(path.dirname(preserved));
	const identityFailure = runCloneSetup('printf unexpected-success', identityFailureBin);
	const uncertainBundles = fs
		.readdirSync(path.dirname(preserved))
		.filter((name) => !beforeIdentityFailure.includes(name));
	test(
		'an identity capture failure reports the error and preserves an unadmitted destination',
		identityFailure.status === 78 &&
			identityFailure.stdout.includes('cannot capture reserved bundle ownership') &&
			identityFailure.stdout.includes('reserved bundle ownership changed; refusing cleanup') &&
			uncertainBundles.length === 1 &&
			fs.statSync(path.join(path.dirname(preserved), uncertainBundles[0])).isDirectory() &&
			!identityFailure.stdout.includes('unexpected-success'),
		JSON.stringify({
			status: identityFailure.status,
			stdout: identityFailure.stdout,
			stderr: identityFailure.stderr,
			uncertainBundles
		})
	);

	const completed = runCloneSetup('CLONE_COMPLETE=1; printf "%s\\0%s\\0" "$DEST" "$TMPDIR_WORK"');
	const [completedDestination, completedTemporary] = decodeNulFields(Buffer.from(completed.stdout));
	test(
		'a completed clone keeps its owned bundle while retiring its temporary workspace',
		completed.status === 0 &&
			completedDestination &&
			completedTemporary &&
			fs.statSync(nativeFixturePath(completedDestination)).isDirectory() &&
			!fs.existsSync(nativeFixturePath(completedTemporary)),
		JSON.stringify({ status: completed.status, stdout: completed.stdout, stderr: completed.stderr })
	);
	const receiptFailure = runCloneSetup(
		'printf "%s\\0%s\\0" "$DEST" "$TMPDIR_WORK"; CLONE_COMPLETE=1; exec 1>&-; printf unavailable-output'
	);
	const [publishedDestination, retiredTemporary] = decodeNulFields(
		Buffer.from(receiptFailure.stdout)
	);
	test(
		'a completed bundle survives failure to write its final success receipt',
		receiptFailure.status !== 0 &&
			publishedDestination &&
			retiredTemporary &&
			fs.statSync(nativeFixturePath(publishedDestination)).isDirectory() &&
			!fs.existsSync(nativeFixturePath(retiredTemporary)),
		JSON.stringify({
			status: receiptFailure.status,
			stdout: receiptFailure.stdout,
			stderr: receiptFailure.stderr
		})
	);

	test(
		'clone rollback preserves pre-existing same-name bundles and symbolic links',
		fs.readFileSync(path.join(preserved, 'owned-marker'), 'utf8') === 'pre-existing bundle' &&
			fs.lstatSync(preservedLink).isSymbolicLink() &&
			fs.realpathSync(preservedLink) === fs.realpathSync(preserved),
		JSON.stringify(fs.readdirSync(path.dirname(preserved)))
	);

	const collisionRuns = [];
	for (const target of ['first-target', 'second-target', 'third-target']) {
		const run = spawnSync(
			bash,
			[
				toBashPath(SHORTCUT_SCRIPT),
				'Collision',
				target,
				'/Applications/Editor.app',
				'#123456',
				'C'
			],
			{
				encoding: 'utf8',
				env: {
					...process.env,
					HOME: toBashPath(home),
					REAL_PYTHON: realPython.stdout.trim(),
					PATH: `${toBashPath(fakeBin)}:${process.env.PATH || ''}`
				}
			}
		);
		const destination = nativeFixturePath((run.stdout || '').trim());
		collisionRuns.push({
			run,
			destination,
			launcher: fs.readFileSync(path.join(destination, 'Contents', 'MacOS', 'open_target'), 'utf8')
		});
	}
	test(
		'same-second shortcut creation reserves three separate bundles without overwriting earlier launchers',
		collisionRuns.every(({ run }) => run.status === 0) &&
			new Set(collisionRuns.map(({ destination }) => destination)).size === 3 &&
			collisionRuns.every(
				({ destination, launcher }) =>
					fs.readFileSync(path.join(destination, 'Contents', 'MacOS', 'open_target'), 'utf8') ===
					launcher
			),
		JSON.stringify(
			collisionRuns.map(({ destination, run }) => ({ destination, status: run.status }))
		)
	);
	const reserveHelper = toBashPath(path.join(RESOURCES, 'reserve_bundle.sh'));
	const occupied = path.join(fixtureRoot, 'Occupied.app');
	fs.writeFileSync(occupied, 'unrelated original file');
	fs.symlinkSync(
		path.join(fixtureRoot, 'missing-target'),
		path.join(fixtureRoot, 'Occupied_1.app'),
		'junction'
	);
	const reservation = spawnSync(
		bash,
		[
			'-c',
			'set -eu; source "$1"; reserve_bundle_directory "$2"',
			'reservation',
			reserveHelper,
			toBashPath(occupied)
		],
		{ encoding: 'utf8' }
	);
	test(
		'bundle reservation preserves occupied files and dangling symbolic links',
		reservation.status === 0 &&
			reservation.stdout.trim() === toBashPath(path.join(fixtureRoot, 'Occupied_2.app')) &&
			fs.readFileSync(occupied, 'utf8') === 'unrelated original file' &&
			fs.lstatSync(path.join(fixtureRoot, 'Occupied_1.app')).isSymbolicLink(),
		reservation.stderr || reservation.stdout
	);
	const refused = spawnSync(
		bash,
		[
			'-c',
			'set -eu; source "$1"; reserve_bundle_directory "$2"; printf unexpected-success',
			'reservation',
			reserveHelper,
			`${toBashPath(occupied)}/Forbidden.app`
		],
		{ encoding: 'utf8' }
	);
	test(
		'a real ENOTDIR reservation refusal is fatal and never reports a destination',
		refused.status !== 0 &&
			refused.stdout === '' &&
			refused.stderr.includes('cannot reserve bundle directory') &&
			fs.readFileSync(occupied, 'utf8') === 'unrelated original file',
		JSON.stringify({ status: refused.status, stdout: refused.stdout, stderr: refused.stderr })
	);
} finally {
	fs.rmSync(fixtureRoot, { recursive: true, force: true });
}

console.log('TAP version 14');
console.log(`1..${results.length}`);
results.forEach((result, index) => {
	console.log(`${result.ok ? 'ok' : 'not ok'} ${index + 1} - ${result.name}`);
	if (!result.ok && result.detail) console.log(`  # ${result.detail}`);
});
console.log(`# passed: ${results.filter((result) => result.ok).length}/${results.length}`);
if (results.some((result) => !result.ok)) process.exitCode = 1;
